function f(n){if(n==null||!Number.isFinite(n)||n<0)return"0:00";const t=Math.floor(n);return`${Math.floor(t/60)}:${String(t%60).padStart(2,"0")}`}function l(n){return Math.max(0,n-1.5)}function c(n,t){for(const[e,i]of n)if(t>=e&&t<=i)return{start:e,end:i};return null}function m(n,t){return n.slice(t.start,t.end+1).map(e=>e.w).join(" ").trim()}function d(n){return n.some(t=>Number.isFinite(t.s)&&Number.isFinite(t.e)&&(t.s!==0||t.e!==0))}function h(n,t){if(!n.length||!Number.isFinite(t)||t<0)return-1;let e=0,i=n.length-1,r=-1;for(;e<=i;){const a=e+i>>1;n[a].s<=t?(r=a,e=a+1):i=a-1}if(r===-1)return-1;const u=n[r];return Number.isFinite(u.e)&&t>u.e+.35?-1:r}function b(n,t){const e=n[t.start],i=n[t.end];if(!e||!i)return null;const r=e.s,u=i.e;return!Number.isFinite(r)||!Number.isFinite(u)||u<=r?null:{a:r,b:u+.25}}function g(n,t){const e=[],i=(r,u,a)=>{if(!(a-u+1<3))for(let o=u+1;o<=a-1;o++){const s=n[o];!s||!/[A-Za-z0-9]/.test(s.w)||e.push({wordIndex:o,sentenceIndex:r,answer:s.w})}};return t.length?t.forEach(([r,u],a)=>i(a,r,u)):n.length&&i(0,0,n.length-1),e}function N(n,t){return t?Math.round(n/t*100):0}function F(n){if(!n)return"—";const t=new Date(n);return Number.isNaN(t.getTime())?"—":t.toLocaleString("zh-CN",{year:"numeric",month:"2-digit",day:"2-digit",hour:"2-digit",minute:"2-digit"})}function p(n){return{llm:"混合出题",nouns:"本地规则",manual:"手动标注",dictation:"全篇听写"}[n]||n}function T(n){return{asr:"语音识别",aligned:"原文对齐",manual:"纯文本"}[n]||n}export{f as a,h as b,l as c,b as d,c as e,F as f,g,d as h,p as m,N as p,m as s,T as t};
